/* Neo Brutalism Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="neo-brutalism-light"] {
  --background: rgb(255, 255, 255);
  --foreground: rgb(0, 0, 0);
  --card: rgb(255, 255, 255);
  --card-foreground: rgb(0, 0, 0);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(0, 0, 0);
  --primary: rgb(255, 53, 52);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(254, 255, 85);
  --secondary-foreground: rgb(0, 0, 0);
  --muted: rgb(242, 242, 242);
  --muted-foreground: rgb(51, 51, 51);
  --accent: rgb(0, 101, 253);
  --accent-foreground: rgb(255, 255, 255);
  --destructive: rgb(0, 0, 0);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(0, 0, 0);
  --input: rgb(0, 0, 0);
  --ring: rgb(255, 53, 52);
  --chart-1: rgb(255, 53, 52);
  --chart-2: rgb(254, 255, 85);
  --chart-3: rgb(0, 101, 253);
  --chart-4: rgb(0, 203, 0);
  --chart-5: rgb(202, 3, 202);
  --radius: 0px;
  --sidebar: rgb(242, 242, 242);
  --sidebar-foreground: rgb(0, 0, 0);
  --sidebar-primary: rgb(255, 53, 52);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(0, 101, 253);
  --sidebar-accent-foreground: rgb(255, 255, 255);
  --sidebar-border: rgb(0, 0, 0);
  --sidebar-ring: rgb(255, 53, 52);
  --font-sans: DM Sans, sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: Space Mono, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 1;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 4px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 4px 4px 0px 0px hsl(0 0% 0% / 0.5);
  --shadow-xs: 4px 4px 0px 0px hsl(0 0% 0% / 0.5);
  --shadow-sm:
    4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 1px 2px -1px hsl(0 0% 0% / 1);
  --shadow: 4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 1px 2px -1px hsl(0 0% 0% / 1);
  --shadow-md:
    4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 2px 4px -1px hsl(0 0% 0% / 1);
  --shadow-lg:
    4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 4px 6px -1px hsl(0 0% 0% / 1);
  --shadow-xl:
    4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 8px 10px -1px hsl(0 0% 0% / 1);
  --shadow-2xl: 4px 4px 0px 0px hsl(0 0% 0% / 2.5);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="neo-brutalism-dark"] {
  --background: rgb(0, 0, 0);
  --foreground: rgb(255, 255, 255);
  --card: rgb(51, 51, 51);
  --card-foreground: rgb(255, 255, 255);
  --popover: rgb(51, 51, 51);
  --popover-foreground: rgb(255, 255, 255);
  --primary: rgb(255, 99, 100);
  --primary-foreground: rgb(0, 0, 0);
  --secondary: rgb(254, 255, 77);
  --secondary-foreground: rgb(0, 0, 0);
  --muted: rgb(51, 51, 51);
  --muted-foreground: rgb(206, 206, 206);
  --accent: rgb(55, 155, 255);
  --accent-foreground: rgb(0, 0, 0);
  --destructive: rgb(255, 255, 255);
  --destructive-foreground: rgb(0, 0, 0);
  --border: rgb(255, 255, 255);
  --input: rgb(255, 255, 255);
  --ring: rgb(255, 99, 100);
  --chart-1: rgb(255, 99, 100);
  --chart-2: rgb(254, 255, 77);
  --chart-3: rgb(55, 155, 255);
  --chart-4: rgb(47, 205, 48);
  --chart-5: rgb(204, 46, 204);
  --radius: 0px;
  --sidebar: rgb(0, 0, 0);
  --sidebar-foreground: rgb(255, 255, 255);
  --sidebar-primary: rgb(255, 99, 100);
  --sidebar-primary-foreground: rgb(0, 0, 0);
  --sidebar-accent: rgb(55, 155, 255);
  --sidebar-accent-foreground: rgb(0, 0, 0);
  --sidebar-border: rgb(255, 255, 255);
  --sidebar-ring: rgb(255, 99, 100);
  --font-sans: DM Sans, sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: Space Mono, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 1;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 4px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 4px 4px 0px 0px hsl(0 0% 0% / 0.5);
  --shadow-xs: 4px 4px 0px 0px hsl(0 0% 0% / 0.5);
  --shadow-sm:
    4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 1px 2px -1px hsl(0 0% 0% / 1);
  --shadow: 4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 1px 2px -1px hsl(0 0% 0% / 1);
  --shadow-md:
    4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 2px 4px -1px hsl(0 0% 0% / 1);
  --shadow-lg:
    4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 4px 6px -1px hsl(0 0% 0% / 1);
  --shadow-xl:
    4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 8px 10px -1px hsl(0 0% 0% / 1);
  --shadow-2xl: 4px 4px 0px 0px hsl(0 0% 0% / 2.5);
}
